package com.campusfix.util;

import com.campusfix.exception.ValidationException;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Complaint ids are generated by the database (AUTO_INCREMENT, so they are always unique).
 * This class only converts between the number stored in the database and the friendly
 * form shown to users, e.g. {@code 12 <-> CF-000012}.
 */
public final class IdGenerator {

    private static final String PREFIX = "CF-";
    private static final Pattern ID_PATTERN = Pattern.compile("^(?:CF-)?(\\d{1,9})$", Pattern.CASE_INSENSITIVE);

    private IdGenerator() { }

    public static String formatComplaintId(int id) {
        return String.format("%s%06d", PREFIX, id);
    }

    /**
     * Accepts "CF-000012", "cf-12" or "12".
     *
     * @throws ValidationException if the text is not a valid complaint id
     */
    public static int parseComplaintId(String text) {
        if (text == null) {
            throw new ValidationException("Complaint ID is required.");
        }
        Matcher m = ID_PATTERN.matcher(text.trim());
        if (!m.matches()) {
            throw new ValidationException("Invalid complaint ID. Use a format like CF-000012 or 12.");
        }
        int id = Integer.parseInt(m.group(1));
        if (id <= 0) {
            throw new ValidationException("Complaint ID must be a positive number.");
        }
        return id;
    }
}
